/**
 * Shared formatting utilities for the Account Manager app.
 * Extracted to avoid duplication across views.
 */

/**
 * Format a number as Brazilian Real currency.
 * @param {number} value
 * @returns {string} formatted currency string (e.g. "R$ 1.234,56")
 */
export function formatCurrency(value) {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(value);
}

/**
 * Format a date string to Brazilian locale.
 * @param {string} dateStr - ISO date string
 * @returns {string} formatted date (e.g. "01/01/2024")
 */
export function formatDate(dateStr) {
  if (!dateStr) return '--';
  return new Intl.DateTimeFormat('pt-BR').format(new Date(dateStr));
}

/**
 * Format a month index (0-11) to its Portuguese name.
 * @param {number} index - month index (0 = January)
 * @returns {string} month name in Portuguese
 */
export function formatMonth(index) {
  const months = [
    'Janeiro', 'Fevereiro', 'Março', 'Abril',
    'Maio', 'Junho', 'Julho', 'Agosto',
    'Setembro', 'Outubro', 'Novembro', 'Dezembro',
  ];
  return months[index] || '';
}

/**
 * Get array of month names in Portuguese.
 * @returns {string[]}
 */
export function getMonths() {
  return [
    'Janeiro', 'Fevereiro', 'Março', 'Abril',
    'Maio', 'Junho', 'Julho', 'Agosto',
    'Setembro', 'Outubro', 'Novembro', 'Dezembro',
  ];
}

/**
 * Get array of years starting from current year.
 * @param {number} range - number of years to include
 * @returns {number[]}
 */
export function getYears(range = 5) {
  const currentYear = new Date().getFullYear();
  return Array.from({ length: range }, (_, i) => currentYear + i);
}
