/**
 * Account service layer — all Supabase CRUD operations for accounts.
 * Extracted from views for reusability and separation of concerns.
 */
import supabase from '@/utils/supabase';

export const accountService = {
  /**
   * Get the currently authenticated user.
   * @returns {Promise<object|null>} user object or null
   * @throws on auth error
   */
  async getCurrentUser() {
    const {
      data: { user },
      error,
    } = await supabase.auth.getUser();
    if (error) throw error;
    return user;
  },

  /**
   * Fetch overdue account parcels (past due, not paid).
   * @returns {Promise<object>} { [monthYear]: { count, totalAmount } }
   */
  async fetchOverdueAccounts() {
    const today = new Date().toISOString();

    const { data, error } = await supabase
      .from('account_parcelas')
      .select('dt_vencimento, valor_parcela')
      .lt('dt_vencimento', today)
      .is('dt_pagamento', null)
      .order('dt_vencimento', { ascending: false });

    if (error) throw error;

    const grouped = {};
    (data || []).forEach((parcela) => {
      const date = new Date(parcela.dt_vencimento);
      const monthYear = `${date.toLocaleString('pt-BR', {
        month: 'long',
      })} ${date.getFullYear()}`;

      if (!grouped[monthYear]) {
        grouped[monthYear] = { count: 0, totalAmount: 0 };
      }
      grouped[monthYear].count += 1;
      grouped[monthYear].totalAmount += Number(parcela.valor_parcela || 0);
    });

    return grouped;
  },

  /**
   * Fetch account parcels for a specific month/year.
   * @param {string} userId
   * @param {number} year
   * @param {number} month - 0-based month index
   * @returns {Promise<Array>} list of parcels with joined account data
   */
  async fetchAccountsByMonth(userId, year, month) {
    const startOfMonth = new Date(year, month, 1).toISOString();
    const endOfMonth = new Date(year, month + 1, 0).toISOString();

    const { data, error } = await supabase
      .from('account_parcelas')
      .select('*, account:id_account(*)')
      .eq('account.user_id', userId)
      .gte('dt_vencimento', startOfMonth)
      .lte('dt_vencimento', endOfMonth)
      .order('dt_vencimento', { ascending: true });

    if (error) throw error;
    return data || [];
  },

  /**
   * Create an account with its installments.
   * @param {object} accountData - { ds_nome, categoria, dia_vencimento, user_id }
   * @param {Array} parcelas - array of { numero_parcela, valor_parcela, dt_vencimento, status }
   * @returns {Promise<object>} the created account record
   */
  async createAccount(accountData, parcelas) {
    // Insert account
    const { data: accountResult, error: accountError } = await supabase
      .from('account')
      .insert({
        ds_nome: accountData.ds_nome,
        valor_total:
          accountData.valor_parcela * accountData.nr_parcelas,
        dia_vencimento: accountData.dia_vencimento,
        user_id: accountData.user_id,
        categoria: accountData.categoria,
      })
      .select();

    if (accountError) throw accountError;

    // Insert parcels
    const accountsParcelas = parcelas.map((p) => ({
      id_account: accountResult[0].id,
      ...p,
    }));

    const { error: parcelasError } = await supabase
      .from('account_parcelas')
      .insert(accountsParcelas);

    if (parcelasError) throw parcelasError;

    return accountResult[0];
  },

  /**
   * Update a single parcel field.
   * @param {number} parcelaId
   * @param {object} updates - { [field]: newValue }
   * @returns {Promise<void>}
   */
  async updateParcela(parcelaId, updates) {
    const { error } = await supabase
      .from('account_parcelas')
      .update(updates)
      .eq('id', parcelaId);

    if (error) throw error;
  },

  /**
   * Delete a single parcel by ID.
   * @param {number} parcelaId
   * @returns {Promise<void>}
   */
  async deleteParcela(parcelaId) {
    const { error } = await supabase
      .from('account_parcelas')
      .delete()
      .eq('id', parcelaId);

    if (error) throw error;
  },
};
