<template>
  <div class="container">
    <div class="d-flex align-items-center justify-content-between mb-4">
      <div>
        <h2 class="page-title mb-1">Dashboard</h2>
        <p class="page-subtitle">Visão geral das suas contas</p>
      </div>
    </div>

    <!-- Loading -->
    <div v-if="loading" class="row g-4">
      <div v-for="n in 4" :key="n" class="col-md-6">
        <div class="skeleton skeleton-card" />
      </div>
    </div>

    <!-- Empty state -->
    <div v-else-if="Object.keys(overdueAccounts).length === 0" class="empty-state-dashboard">
      <div class="empty-icon-circle">
        <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" fill="currentColor" class="bi bi-check-circle-fill" viewBox="0 0 16 16">
          <path d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0zm-3.97-3.03a.75.75 0 0 0-1.08.022L7.477 9.417 5.384 7.323a.75.75 0 0 0-1.06 1.06L6.97 11.03a.75.75 0 0 0 1.079-.02l3.992-4.99a.75.75 0 0 0-.01-1.05z"/>
        </svg>
      </div>
      <h3 class="empty-title">Tudo em dia!</h3>
      <p class="empty-text">Nenhuma conta em atraso no momento.</p>
    </div>

    <!-- Overdue accounts grid -->
    <div v-else class="row g-4">
      <div v-for="(info, month) in overdueAccounts" :key="month" class="col-md-6 col-lg-4 stagger-enter-active">
        <div class="overdue-card">
          <div class="overdue-card-header">
            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" fill="currentColor" class="bi bi-exclamation-triangle-fill me-2" viewBox="0 0 16 16">
              <path d="M8.982 1.566a1.13 1.13 0 0 0-1.96 0L.165 13.233c-.457.778.091 1.767.98 1.767h13.713c.889 0 1.438-.99.98-1.767L8.982 1.566zM8 5c.535 0 .954.462.9.995l-.35 3.507a.552.552 0 0 1-1.1 0L7.1 5.995A.905.905 0 0 1 8 5zm.002 6a1 1 0 1 1 0 2 1 1 0 0 1 0-2z"/>
            </svg>
            {{ month }}
          </div>
          <div class="overdue-card-body">
            <div class="overdue-stat">
              <span class="overdue-label">Total de Contas</span>
              <span class="overdue-value">{{ info.count }}</span>
            </div>
            <div class="overdue-stat">
              <span class="overdue-label">Valor Total</span>
              <span class="overdue-value overdue-amount">{{ formatCurrency(info.totalAmount) }}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { ref, onMounted } from 'vue';
import { useToast } from 'vue-toastification';
import { formatCurrency } from '@/utils/formatters';
import { accountService } from '@/services/accountService';

export default {
  name: 'DashboardView',
  setup() {
    const toast = useToast();
    const overdueAccounts = ref({});
    const loading = ref(true);

    onMounted(fetchOverdueAccounts);

    async function fetchOverdueAccounts() {
      try {
        const user = await accountService.getCurrentUser();
        if (!user) return;

        const grouped = await accountService.fetchOverdueAccounts();
        overdueAccounts.value = grouped;
      } catch (err) {
        console.error('Erro ao buscar contas:', err.message);
        toast.error('Erro ao carregar dados do dashboard.');
      } finally {
        loading.value = false;
      }
    }

    return {
      overdueAccounts,
      loading,
      formatCurrency,
    };
  },
};
</script>

